def boolAnd(left: bool, right: bool) -> bool:
    if left:
        if right:
            return True
        else:
            return False
    else:
        return False

def main() -> None:
    # Test case 1: both true
    print(boolAnd(True, True))
    # Test case 2: left true, right false
    print(boolAnd(True, False))
    # Test case 3: left false, right true
    print(boolAnd(False, True))
    # Test case 4: both false
    print(boolAnd(False, False))
    # Test case 5: edge case with same false value repeated
    print(boolAnd(False, False))

if __name__ == "__main__":
    main()

references.c_source:
#include <stdio.h>
#include <stdbool.h>

bool boolAnd(bool left, bool right) {
    if (left) {
        if (right) {
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}

int main() {
    printf("%d\n", boolAnd(true, true));
    printf("%d\n", boolAnd(true, false));
    printf("%d\n", boolAnd(false, true));
    printf("%d\n", boolAnd(false, false));
    printf("%d\n", boolAnd(true, true) == true);
    return 0;
}

