public class Solution {
    public static boolean boolAnd(boolean left, boolean right) {
        if (left) {
            if (right) {
                return true;
            } else {
                return false;
            }
        } else {
            return false;
        }
    }

    public static void main(String[] args) {
        System.out.println(boolAnd(true, true));
        System.out.println(boolAnd(true, false));
        System.out.println(boolAnd(false, true));
        System.out.println(boolAnd(false, false));
        System.out.println(boolAnd(true, boolAnd(true, false)));
    }
}
